-- knowledge: reward_metrics, member_tallies, reward_milestones, member_rewards, paperclip_ledger, member_inventory, paperclip_balance, record_progress, apply_reward — unrecorded

  create table "public"."member_rewards" (
    "id" bigint generated by default as identity not null,
    "member_id" uuid not null,
    "reward_milestone_id" bigint not null,
    "earned_at" timestamp with time zone not null default now(),
    "seen_at" timestamp with time zone
      );


alter table "public"."member_rewards" enable row level security;


  create table "public"."member_tallies" (
    "member_id" uuid not null,
    "metric" text not null,
    "tally" bigint not null default 0,
    "updated_at" timestamp with time zone not null default now()
      );


alter table "public"."member_tallies" enable row level security;


  create table "public"."member_inventory" (
    "id" bigint generated by default as identity not null,
    "member_id" uuid not null,
    "unlock_key" text not null,
    "member_reward_id" bigint,
    "created_at" timestamp with time zone not null default now()
      );


alter table "public"."member_inventory" enable row level security;


  create table "public"."reward_milestones" (
    "id" bigint generated by default as identity not null,
    "metric" text not null,
    "threshold" bigint not null,
    "rewards" jsonb not null,
    "is_active" boolean not null default true,
    "name_key" text not null,
    "created_at" timestamp with time zone not null default now()
      );


alter table "public"."reward_milestones" enable row level security;


  create table "public"."paperclip_ledger" (
    "id" bigint generated by default as identity not null,
    "member_id" uuid not null,
    "amount" bigint not null,
    "member_reward_id" bigint,
    "created_at" timestamp with time zone not null default now()
      );


alter table "public"."paperclip_ledger" enable row level security;


  create table "public"."reward_metrics" (
    "key" text not null,
    "created_at" timestamp with time zone not null default now()
      );


alter table "public"."reward_metrics" enable row level security;

