  create policy "members can view their own earned rewards"
  on "public"."member_rewards"
  as permissive
  for select
  to authenticated
using ((( SELECT public.active_member_id() AS active_member_id) = member_id));



  create policy "members can view their own tallies"
  on "public"."member_tallies"
  as permissive
  for select
  to authenticated
using ((( SELECT public.active_member_id() AS active_member_id) = member_id));



  create policy "members can view their own inventory"
  on "public"."member_inventory"
  as permissive
  for select
  to authenticated
using ((( SELECT public.active_member_id() AS active_member_id) = member_id));



  create policy "active milestones readable by authenticated users"
  on "public"."reward_milestones"
  as permissive
  for select
  to authenticated
using ((is_active = true));



  create policy "members can view their own ledger"
  on "public"."paperclip_ledger"
  as permissive
  for select
  to authenticated
using ((( SELECT public.active_member_id() AS active_member_id) = member_id));



  create policy "metrics readable by authenticated users"
  on "public"."reward_metrics"
  as permissive
  for select
  to authenticated
using (true);


-- Hand-written: db diff emits no function grants, so without these the two
-- internal definer functions land EXECUTE-able by PUBLIC (anon included). They
-- are reusable seams called only from other definer functions, never a client.
revoke all on function public.apply_reward(p_member uuid, p_rewards jsonb, p_member_reward bigint) from public;
revoke all on function public.apply_reward(p_member uuid, p_rewards jsonb, p_member_reward bigint) from anon;
revoke all on function public.apply_reward(p_member uuid, p_rewards jsonb, p_member_reward bigint) from authenticated;
grant all on function public.apply_reward(p_member uuid, p_rewards jsonb, p_member_reward bigint) to service_role;

revoke all on function public.record_progress(p_member uuid, p_metric text, p_delta bigint) from public;
revoke all on function public.record_progress(p_member uuid, p_metric text, p_delta bigint) from anon;
revoke all on function public.record_progress(p_member uuid, p_metric text, p_delta bigint) from authenticated;
grant all on function public.record_progress(p_member uuid, p_metric text, p_delta bigint) to service_role;
